package lec_03_Operators_Variables;

public class Assignment_Operators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int x=9;
		x += 5; // Same as x = x+5
		System.out.println(x);
		x -= 5; // Same as x = x-5
		System.out.println(x);
		x /= 5; // Same as x = x/5
		System.out.println(x);
		x %= 5; // Same as x = x% 5
		System.out.println(x);

	}

}
